	private bool recoverChangeSet(ProjectDtArchiveDB dataTypeArchive, DBHandle dbh)
    {
		bool recovered = false;
		DataTypeArchiveDBChangeSet changeSet =
			(DataTypeArchiveDBChangeSet) dataTypeArchive.getChangeSet();
		BufferFile cf = dbh.getRecoveryChangeSetFile();
		if (cf != null) {
			DBHandle cfh = null;
			try {
				cfh = new DBHandle(cf);
				changeSet.read(cfh);
				recovered = true;
			}
			finally {
				if (cfh != null) {
					cfh.close();
				}
				cf.dispose();
			}
		}
		return recovered;
	}

	private DataTypeArchiveDBChangeSet getDataTypeArchiveChangeSet(
			ProjectDtArchiveDB dataTypeArchive, ManagedBufferFile bf)
    {
		DataTypeArchiveDBChangeSet changeSet =
			(DataTypeArchiveDBChangeSet) dataTypeArchive.getChangeSet();
		BufferFile cf = bf.getNextChangeDataFile(true);
		DBHandle cfh = null;
		while (cf != null) {
			try {
				cfh = new DBHandle(cf);
				changeSet.read(cfh);
			}
			finally {
				if (cfh != null) {
					cfh.close();
					cfh = null;
				}
				cf.dispose();
			}
			cf = bf.getNextChangeDataFile(false);
		}
		return changeSet;
	}

